sp_widget.client_script:
api.controller = function() {
  var c = this;

  c.goBack = function() {
    if (window.history.length > 1) {
      window.history.back();
    } else {
      window.location.href = '?id=x_1956908_wareho_0_staff_dashboard';
    }
  };

  c.updateRecord = function() {
    var note = prompt('Enter update notes for this exception:');
    if (note && note.trim()) {
      c.data.action = 'add_note';
      c.data.note = note.trim();
      c.server.update().then(function() {
        alert('Exception updated.');
        c.server.refresh();
      });
    }
  };
};

sp_widget.css:
.wei-detail-wrapper {
  max-width: 860px;
  margin: 30px auto 60px;
  padding: 0 16px;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
}
.wei-detail-card {
  background: #FFFFFF;
  border: 1px solid #E2E8F0;
  border-radius: 8px;
  padding: 28px 32px;
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.04);
}
.wei-detail-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding-bottom: 18px;
  border-bottom: 1px solid #F1F5F9;
  margin-bottom: 24px;
}
.wei-detail-title {
  font-size: 20px;
  font-weight: 700;
  color: #0F172A;
  margin: 0;
}
.wei-badge-lg {
  padding: 6px 14px;
  font-size: 12px;
}

/* 2 Columns */
.wei-detail-columns {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 32px;
  margin-bottom: 28px;
}
@media (max-width: 768px) {
  .wei-detail-columns { grid-template-columns: 1fr; }
}

.wei-field-table {
  margin: 0;
}
.wei-field-table td {
  padding: 8px 0 !important;
  font-size: 13px !important;
  border-top: 1px solid #F8FAFC !important;
}
.wei-field-table .lbl {
  color: #64748B;
  width: 110px;
  font-weight: 500;
}
.wei-field-table .val {
  color: #0F172A;
}

.wei-text-block {
  margin-bottom: 18px;
}
.block-lbl {
  font-size: 12px;
  font-weight: 700;
  color: #475569;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  margin-bottom: 4px;
}
.block-val {
  font-size: 13px;
  color: #1E293B;
  line-height: 1.5;
}
.resolution-box {
  background: #F8FAFC;
  border: 1px solid #E2E8F0;
  border-radius: 6px;
  padding: 10px 14px;
  min-height: 48px;
}

/* Actions Row */
.wei-detail-actions {
  display: flex;
  gap: 12px;
  padding-top: 20px;
  border-top: 1px solid #F1F5F9;
}
.btn-update {
  background: #1976D2;
  border-color: #1976D2;
  font-size: 13px;
  font-weight: 600;
  padding: 8px 24px;
  border-radius: 6px;
}
.btn-update:hover { background: #1565C0; }
.btn-resolve {
  background: #16A34A;
  border-color: #16A34A;
  color: #FFFFFF !important;
  font-size: 13px;
  font-weight: 600;
  padding: 8px 24px;
  border-radius: 6px;
  text-decoration: none !important;
}
.btn-resolve:hover { background: #15803D; }
.btn-back {
  font-size: 13px;
  font-weight: 500;
  padding: 8px 20px;
  border-radius: 6px;
  border: 1px solid #CBD5E1;
  color: #475569;
}

sp_widget.script:
(function() {
  var tableName = 'x_1956908_wareho_0_exception';
  var sysId = ($sp.getParameter('sys_id') || $sp.getParameter('record_id') || '').trim();
  var userId = gs.getUserID();

  data.record = null;
  data.allowed = false;

  var isSup = gs.hasRole('x_1956908_wareho_0.supervisor') || gs.hasRole('x_1956908_wareho_0.admin') || gs.hasRole('admin');
  var isTech = gs.hasRole('x_1956908_wareho_0.technician');
  var isStaff = gs.hasRole('x_1956908_wareho_0.staff');

  if (!sysId) {
    data.error = 'No record specified';
    return;
  }

  // Handle work note addition
  if (input && input.action === 'add_note' && input.note) {
    var grUp = new GlideRecord(tableName);
    if (grUp.get(sysId)) {
      grUp.work_notes = input.note;
      grUp.update();
      data.updated = true;
    }
  }

  var gr = new GlideRecord(tableName);
  if (gr.get(sysId)) {
    var reportedBy = gr.getValue('reported_by');
    var assignedTo = gr.getValue('assigned_to');

    // Security Guard: Staff see only own, Tech only assigned, Sup sees all
    if (isSup) {
      data.allowed = true;
    } else if (isTech && assignedTo === userId) {
      data.allowed = true;
    } else if (isStaff && reportedBy === userId) {
      data.allowed = true;
    }

    if (!data.allowed) {
      data.error = 'Access denied: You are only authorized to view records assigned to or reported by you.';
      return;
    }

    data.canResolve = isTech || isSup;

    var rawType = gr.getValue('exception_type') || '';
    var rawSev = gr.getValue('severity') || 'medium';
    var rawStatus = gr.getValue('status') || 'new';

    var typeLabels = {
      'damaged_goods': 'Damaged Item',
      'inventory_mismatch': 'Missing Item',
      'equipment_malfunction': 'Equipment Issue',
      'safety_incident': 'Safety Concern',
      'process_error': 'Inventory Discrepancy'
    };

    var createdGdt = new GlideDateTime(gr.getValue('sys_created_on'));
    var slaGdt = new GlideDateTime(createdGdt);
    if (rawSev === 'critical') slaGdt.addDaysLocalTime(1);
    else if (rawSev === 'high') slaGdt.addDaysLocalTime(2);
    else if (rawSev === 'medium') slaGdt.addDaysLocalTime(3);
    else slaGdt.addDaysLocalTime(5);

    data.record = {
      sys_id: gr.getUniqueValue(),
      number: gr.getValue('number') || '',
      type: typeLabels[rawType] || gr.getDisplayValue('exception_type') || rawType,
      severity: gr.getDisplayValue('severity') || rawSev,
      severity_raw: rawSev,
      status: gr.getDisplayValue('status') || rawStatus,
      status_raw: rawStatus,
      location: gr.getValue('location') || '',
      opened_by: gr.getDisplayValue('reported_by') || 'staff1',
      assigned_to: gr.getDisplayValue('assigned_to') || 'Unassigned',
      sla_due: slaGdt.getDisplayValue(),
      short_description: gr.getValue('short_description') || '',
      details: gr.getValue('description') || '',
      resolution_notes: gr.getValue('resolution_notes') || ''
    };
  }
})();
